-- ---------------------------------------------------------------------
-- Soundwave APP — student instance for COSC 3337 HW 3
--
-- Generated by generate_soundwave_app.py (seed 333701).  Do not hand-edit.
--
-- The artist / album / track tables are the HW 1 catalog, unchanged, plus one
-- extra artist (A0201).  The listener / playlist / playlist_track / play
-- tables are new: they are what a streaming *application* needs on top of
-- the catalog.
--
-- This script is idempotent.  Running it again restores a clean database:
--
--     mysql < soundwave_app.sql
-- ---------------------------------------------------------------------

DROP DATABASE IF EXISTS soundwave_app;
CREATE DATABASE soundwave_app CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE soundwave_app;

CREATE TABLE artist (
  artist_id    VARCHAR(8)   NOT NULL,
  name         VARCHAR(80)  NOT NULL,
  country      VARCHAR(40)      NULL,
  formed_year  SMALLINT         NULL,
  PRIMARY KEY (artist_id)
) ENGINE=InnoDB;

CREATE TABLE album (
  album_id     VARCHAR(8)   NOT NULL,
  title        VARCHAR(120) NOT NULL,
  artist_id    VARCHAR(8)   NOT NULL,
  release_year SMALLINT         NULL,
  genre        VARCHAR(30)  NOT NULL,
  PRIMARY KEY (album_id),
  CONSTRAINT fk_album_artist
    FOREIGN KEY (artist_id) REFERENCES artist (artist_id)
) ENGINE=InnoDB;

CREATE TABLE track (
  track_id     VARCHAR(8)   NOT NULL,
  album_id     VARCHAR(8)   NOT NULL,
  title        VARCHAR(120) NOT NULL,
  duration_sec INT          NOT NULL,
  PRIMARY KEY (track_id),
  CONSTRAINT fk_track_album
    FOREIGN KEY (album_id) REFERENCES album (album_id)
) ENGINE=InnoDB;

CREATE TABLE listener (
  listener_id  VARCHAR(8)   NOT NULL,
  username     VARCHAR(40)  NOT NULL,
  email        VARCHAR(120) NOT NULL,
  country      VARCHAR(40)      NULL,
  joined_date  DATE         NOT NULL,
  PRIMARY KEY (listener_id),
  UNIQUE KEY uq_listener_username (username)
) ENGINE=InnoDB;

-- playlist_id is AUTO_INCREMENT: the application never chooses it, MySQL does.
CREATE TABLE playlist (
  playlist_id   INT          NOT NULL AUTO_INCREMENT,
  listener_id   VARCHAR(8)   NOT NULL,
  name          VARCHAR(80)  NOT NULL,
  created_date  DATE         NOT NULL,
  PRIMARY KEY (playlist_id),
  CONSTRAINT fk_playlist_listener
    FOREIGN KEY (listener_id) REFERENCES listener (listener_id)
) ENGINE=InnoDB;

-- A track appears at most once in a given playlist; position is 1, 2, 3, ...
CREATE TABLE playlist_track (
  playlist_id  INT         NOT NULL,
  track_id     VARCHAR(8)  NOT NULL,
  position     INT         NOT NULL,
  PRIMARY KEY (playlist_id, track_id),
  CONSTRAINT fk_pt_playlist
    FOREIGN KEY (playlist_id) REFERENCES playlist (playlist_id),
  CONSTRAINT fk_pt_track
    FOREIGN KEY (track_id) REFERENCES track (track_id)
) ENGINE=InnoDB;

-- One row every time a listener plays a track.
CREATE TABLE play (
  play_id      INT         NOT NULL AUTO_INCREMENT,
  listener_id  VARCHAR(8)  NOT NULL,
  track_id     VARCHAR(8)  NOT NULL,
  played_at    DATETIME    NOT NULL,
  PRIMARY KEY (play_id),
  CONSTRAINT fk_play_listener
    FOREIGN KEY (listener_id) REFERENCES listener (listener_id),
  CONSTRAINT fk_play_track
    FOREIGN KEY (track_id) REFERENCES track (track_id)
) ENGINE=InnoDB;






























































